<template>
  <section class="graph-editor" tabindex="0" @keydown="onKeydown">
    <header class="graph-toolbar">
      <div class="primary-actions">
        <button class="primary" @click="createGraph">＋ {{ t('newVisualGraph') }}</button>
        <button :disabled="!activeAsset || !dirty" @click="saveGraph">{{ t('saveAsset') }}</button>
        <button :disabled="!canUndo" :title="t('undo')" @click="undo">↶</button><button :disabled="!canRedo" :title="t('redo')" @click="redo">↷</button>
      </div>
      <select v-model="activeScopeUuid" class="scope-picker" :title="t('graphScope')" @change="scopeChanged">
        <option value="main">{{ t('mainGraph') }}</option>
        <option v-for="routine in graph.routines" :key="routine.uuid" :value="routine.uuid">{{ routine.kind }} · {{ routine.name }}</option>
      </select>
      <div class="editing-actions">
        <button :class="{ active: studio.paletteOpen }" @click="studio.paletteOpen = !studio.paletteOpen">＋ {{ t('nodePalette') }}</button>
        <button :disabled="!selectedNodes.size" @click="duplicateSelected">{{ t('duplicate') }}</button>
        <button :disabled="selectedNodes.size < 2" @click="alignSelected">{{ t('alignLeft') }}</button>
        <button :disabled="selectedNodes.size < 3" @click="distributeSelected">{{ t('distributeHorizontal') }}</button>
        <button @click="addComment">{{ t('graphComment') }}</button>
        <button @click="frameAll">{{ t('frameAll') }}</button>
      </div>
      <span class="graph-status" :class="{ invalid: !validation.valid }">{{ validation.valid ? t('graphReady') : t('graphErrors', { count: errorCount }) }} · {{ activeScope.nodes.length }} {{ t('nodes') }} · {{ validation.elapsedMs.toFixed(1) }} ms</span>
    </header>

    <div class="graph-body" :class="{ 'no-palette': !studio.paletteOpen, 'no-details': !studio.detailsOpen }">
      <aside v-if="studio.paletteOpen" class="graph-palette">
        <header><strong>{{ t('nodePalette') }}</strong><button :title="t('close')" @click="studio.paletteOpen = false">×</button></header>
        <input ref="paletteInput" v-model="paletteSearch" type="search" :placeholder="t('searchNodes')" @keydown.enter.prevent="addFirstPaletteNode">
        <div class="asset-list">
          <button v-for="asset in graphAssets" :key="asset.uuid" :class="{ active: asset.uuid === activeAsset?.uuid }" @click="openGraph(asset.uuid)"><i>⌘</i><span><strong>{{ asset.name }}</strong><small>{{ asset.path }}</small></span></button>
        </div>
        <div class="palette-list">
          <section v-for="group in paletteGroups" :key="group.category"><h3>{{ localizedCategory(group.category) }}</h3><button v-for="definition in group.items" :key="definition.type" :title="definition.description" @click="addNode(definition.type)"><i :style="{ background: definition.color }"></i><span><strong>{{ definition.title }}</strong><small>{{ definition.description }}</small></span></button></section>
          <p v-if="!paletteResults.length" class="empty">{{ t('noMatchingNodes') }}</p>
        </div>
      </aside>

      <main ref="canvas" class="graph-canvas" :class="{ connecting: pendingWire }" @pointerdown="canvasPointerDown" @wheel.prevent="zoomCanvas">
        <div class="graph-grid" :style="gridStyle"></div>
        <svg class="graph-transform wires" :style="transformStyle" aria-hidden="true">
          <path v-for="edge in visibleEdges" :key="edge.uuid" :d="edgePath(edge)" :class="[edgeKind(edge), { active: graphDebugState.activeEdgeUuid === edge.uuid }]" />
          <path v-if="pendingWire && pointerGraph" :d="pendingPath" class="pending" />
        </svg>
        <div class="graph-transform comments" :style="transformStyle">
          <article v-for="comment in activeScope.comments" :key="comment.uuid" class="graph-comment" :class="{ collapsed: comment.collapsed }" :style="commentStyle(comment)" @pointerdown.stop="startCommentDrag($event, comment)"><header :style="{ borderColor: comment.color }"><input v-model="comment.text" maxlength="2048" @change="markDirty"><button @click.stop="comment.collapsed = !comment.collapsed; markDirty()">{{ comment.collapsed ? '+' : '−' }}</button></header></article>
        </div>
        <div class="graph-transform nodes-layer" :style="transformStyle">
          <article v-for="node in visibleNodes" :key="node.uuid" class="graph-node" :class="{ selected: selectedNodes.has(node.uuid), collapsed: node.collapsed, breakpoint: hasBreakpoint(node.uuid), executing: graphDebugState.activeNodeUuid === node.uuid, failed: hasNodeError(node.uuid), covered: graphDebugState.coverage[node.uuid] > 0 }" :style="nodeStyle(node)" @pointerdown.stop="selectNode($event,node)">
            <header :style="{ '--node-color': nodeColor(node) }" @pointerdown.stop="startNodeDrag($event,node)"><button class="breakpoint-toggle" :title="t('toggleBreakpoint')" @pointerdown.stop @click.stop="toggleBreakpoint(node.uuid)"></button><i></i><strong>{{ node.title }}</strong><small>{{ node.category }}</small><button :title="t('collapse')" @click.stop="node.collapsed = !node.collapsed; markDirty()">{{ node.collapsed ? '+' : '−' }}</button></header>
            <div v-if="!node.collapsed" class="node-pins">
              <div v-for="pin in node.pins" :key="pin.uuid" class="node-pin" :class="[pin.direction,pin.kind]">
                <button class="pin-dot" :class="pin.valueType?.toLowerCase()" :title="`${pin.name} · ${pin.kind === 'execution' ? t('executionPin') : pin.valueType}`" @click.stop="pinClicked(node,pin)"></button>
                <span>{{ pin.name }}</span>
                <template v-if="pin.kind === 'data' && pin.direction === 'input' && !pinConnected(pin)">
                  <input v-if="pin.valueType === 'Number'" :value="pin.defaultValue" type="number" step="0.01" @input="updatePinNumber(pin,$event)" @change="setPinNumber(pin,$event)">
                  <input v-else-if="pin.valueType === 'Boolean'" :checked="pin.defaultValue === true" type="checkbox" @change="pin.defaultValue = ($event.target as HTMLInputElement).checked; markDirty()">
                  <div v-else-if="pin.valueType === 'Vec2'" class="vec-input"><input :value="vecPart(pin.defaultValue,0)" type="number" step="0.01" @input="updatePinVector(pin,0,$event)" @change="setPinVector(pin,0,$event)"><input :value="vecPart(pin.defaultValue,1)" type="number" step="0.01" @input="updatePinVector(pin,1,$event)" @change="setPinVector(pin,1,$event)"></div>
                  <input v-else :value="displayPinValue(pin.defaultValue)" type="text" @input="updatePinText(pin,$event)" @change="setPinText(pin,$event)">
                </template>
                <template v-if="node.type.startsWith('literal.') && pin.direction === 'output'">
                  <input v-if="pin.valueType === 'Number'" :value="node.config.value" type="number" step="0.01" @input="updateLiteralNumber(node,$event)" @change="setLiteralNumber(node,$event)">
                  <input v-else-if="pin.valueType === 'Boolean'" :checked="node.config.value === true" type="checkbox" @change="node.config.value = ($event.target as HTMLInputElement).checked; markDirty()">
                  <div v-else-if="pin.valueType === 'Vec2'" class="vec-input"><input :value="vecPart(node.config.value,0)" type="number" step="0.01" @input="updateLiteralVector(node,0,$event)" @change="setLiteralVector(node,0,$event)"><input :value="vecPart(node.config.value,1)" type="number" step="0.01" @input="updateLiteralVector(node,1,$event)" @change="setLiteralVector(node,1,$event)"></div>
                  <input v-else :value="displayPinValue(node.config.value)" type="text" @input="updateLiteralText(node,$event)" @change="setLiteralText(node,$event)">
                </template>
              </div>
            </div>
            <select v-if="node.type.startsWith('variable.') && !node.collapsed" :value="node.config.variableUuid" @change="selectNodeVariable(node,$event)"><option value="">{{ t('selectVariable') }}</option><option v-for="variable in graph.variables" :key="variable.uuid" :value="variable.uuid">{{ variable.name }} · {{ variable.valueType }}</option></select>
            <select v-if="node.type.startsWith('local.') && activeRoutine && !node.collapsed" :value="node.config.localUuid" @change="selectNodeLocal(node,$event)"><option value="">{{ t('selectLocal') }}</option><option v-for="local in activeRoutine.locals" :key="local.uuid" :value="local.uuid">{{ local.name }} · {{ local.valueType }}</option></select>
            <section v-if="!node.collapsed && (node.type.startsWith('code.') || typeof node.config.rhaiSourceOverride === 'string')" class="node-source" @pointerdown.stop>
              <span>{{ node.config.rhaiSourceOverride ? t('linkedCodeOverride') : t('generatedRhai') }}</span>
              <textarea :value="nodeCodeSource(node)" spellcheck="false" @input="updateNodeCodeSource(node,$event)" @change="setNodeCodeSource(node,$event)"></textarea>
              <button v-if="node.config.rhaiSourceOverride" @click="clearNodeCodeOverride(node)">{{ t('clearCodeOverride') }}</button>
            </section>
          </article>
        </div>
        <div v-if="selectionBox" class="selection-box" :style="selectionBoxStyle"></div>
        <div class="canvas-controls"><button @click.stop="changeZoom(-.1)">−</button><span>{{ Math.round(activeScope.viewport.zoom * 100) }}%</span><button @click.stop="changeZoom(.1)">＋</button><button :class="{ active: studio.minimapOpen }" @click.stop="studio.minimapOpen = !studio.minimapOpen">▣</button></div>
        <aside v-if="studio.minimapOpen" class="minimap" @pointerdown.stop><header>{{ t('minimap') }}</header><svg viewBox="0 0 200 120"><rect v-for="node in activeScope.nodes" :key="node.uuid" :x="miniX(node.position.x)" :y="miniY(node.position.y)" width="8" height="5" :class="{ selected: selectedNodes.has(node.uuid) }" /></svg></aside>
        <button v-if="!studio.paletteOpen" class="open-palette" @click.stop="studio.paletteOpen = true">＋ {{ t('nodes') }}</button>
      </main>

      <aside v-if="studio.detailsOpen" class="graph-details">
        <header><strong>{{ t('graphDetails') }}</strong><button :title="t('close')" @click="studio.detailsOpen = false">×</button></header>
        <section class="graph-summary"><label><span>{{ t('graphName') }}</span><input v-model="graph.name" maxlength="120" @change="markDirty"></label><div><span>Format {{ graph.version }}</span><span>Rhai API {{ graph.apiVersion }}</span></div></section>
        <GraphProductionPanel :graph="graph" :scope-uuid="activeScopeUuid" :selected-node-uuids="[...selectedNodes]" :compiled-source="compileResult.source" @dirty="markDirty" @scope="setActiveScope" @replace-graph="replaceGraph" />
        <section class="variables"><header><strong>{{ t('graphVariables') }}</strong><button @click="addVariable">＋</button></header><article v-for="variable in graph.variables" :key="variable.uuid"><div><input v-model="variable.name" maxlength="80" @change="normalizeVariable(variable)"><select v-model="variable.valueType" @change="variableTypeChanged(variable)"><option v-for="type in valueTypes" :key="type">{{ type }}</option></select><button class="danger" @click="removeVariable(variable.uuid)">×</button></div><label><input v-model="variable.exposed" type="checkbox" @change="markDirty"><span>{{ t('exposeInInspector') }}</span></label><input v-model="variable.group" :placeholder="t('group')" maxlength="80" @change="markDirty"><input v-model="variable.tooltip" :placeholder="t('tooltip')" maxlength="512" @change="markDirty"><div v-if="variable.valueType === 'Number'" class="number-metadata"><input v-model.number="variable.minimum" type="number" :placeholder="t('minimum')" @change="markDirty"><input v-model.number="variable.maximum" type="number" :placeholder="t('maximum')" @change="markDirty"><input v-model.number="variable.step" type="number" min="0.000001" :placeholder="t('step')" @change="markDirty"></div><input :value="displayPinValue(variable.defaultValue)" :placeholder="t('defaultValue')" @change="setVariableDefault(variable,$event)"></article><p v-if="!graph.variables.length">{{ t('noGraphVariables') }}</p></section>
        <section class="diagnostics"><header><strong>{{ t('validation') }}</strong><button @click="showCompiled = !showCompiled">{{ showCompiled ? t('problems') : t('generatedRhai') }}</button></header><template v-if="!showCompiled"><button v-for="diagnostic in validation.diagnostics" :key="`${diagnostic.code}:${diagnostic.nodeUuid}:${diagnostic.pinUuid}`" :class="diagnostic.severity" @click="focusDiagnostic(diagnostic)"><i></i><span><strong>{{ diagnostic.code }}</strong><small>{{ diagnostic.message }}</small></span></button><p v-if="!validation.diagnostics.length" class="valid">✓ {{ t('graphValidationPassed') }}</p></template><pre v-else>{{ compileResult.source || t('graphCannotCompile') }}</pre></section>
      </aside>
      <button v-if="!studio.detailsOpen" class="open-details" @click="studio.detailsOpen = true">{{ t('graphDetails') }} ‹</button>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, shallowRef, triggerRef, watch } from 'vue'
import { assetState, createTextAsset, readTextAsset, updateTextAsset } from '../assets/AssetDatabase'
import { addEditorLog } from '../store/editor'
import { pushHistory } from '../store/physics'
import { t } from '../i18n'
import { createGraphNode, defaultVisualGraph, graphNodeDefinition, searchGraphNodeCatalog, type GraphNodeDefinition } from '../visual/graphCatalog'
import { compileGraph, type GraphDiagnostic } from '../visual/graphCompiler'
import { graphStudioState as studio, openGraphAsset } from '../visual/graphStudioState'
import { defaultGraphValue, graphUuid, parseGraphDocument, serializeGraphDocument, type GraphCanvasScope, type GraphComment, type GraphEdge, type GraphNode, type GraphPin, type GraphValue, type GraphValueType, type GraphVariable, type NovaGraphDocument } from '../visual/graphTypes'
import { graphDebugState } from '../visual/graphDebugger'
import { synchronizeLinkedScriptsForGraph } from '../visual/graphCodeSync'
import GraphProductionPanel from './GraphProductionPanel.vue'
import { gameplayRuntime } from '../runtime/GameplayRuntime'

const canvas = ref<HTMLElement | null>(null), paletteInput = ref<HTMLInputElement | null>(null)
const graph = shallowRef<NovaGraphDocument>(defaultVisualGraph()), dirty = ref(false), paletteSearch = ref(''), showCompiled = ref(false)
const activeScopeUuid = ref('main')
const selectedNodes = reactive(new Set<string>()), pendingWire = shallowRef<{ node: GraphNode; pin: GraphPin } | null>(null), pointerGraph = shallowRef<{ x: number; y: number } | null>(null)
const history = ref<string[]>([]), historyIndex = ref(-1), restoring = ref(false), canvasSize = reactive({ width: 900, height: 600 })
const selectionBox = ref<{ startX: number; startY: number; x: number; y: number; width: number; height: number } | null>(null)
let resizeObserver: ResizeObserver | null = null, compileTimer: number | undefined

const graphAssets = computed(() => { void assetState.generation; return assetState.records.filter(asset => asset.assetType === 'visualScript').sort((a,b) => a.path.localeCompare(b.path)) })
const activeAsset = computed(() => graphAssets.value.find(asset => asset.uuid === studio.activeGraphUuid) ?? null)
const activeRoutine = computed(() => graph.value.routines.find(routine => routine.uuid === activeScopeUuid.value) ?? null)
const activeScope = computed<GraphCanvasScope>(() => activeRoutine.value ?? graph.value)
const compileResult = shallowRef(compileGraph(graph.value)), validation = computed(() => compileResult.value), errorCount = computed(() => validation.value.diagnostics.filter(item => item.severity === 'error').length)
const canUndo = computed(() => historyIndex.value > 0), canRedo = computed(() => historyIndex.value >= 0 && historyIndex.value < history.value.length - 1)
const valueTypes: GraphValueType[] = ['Boolean','Number','String','Vec2','Entity','Resource','Data']
const paletteResults = computed(() => searchGraphNodeCatalog(paletteSearch.value, graph.value, activeRoutine.value).slice(0, 240))
const paletteGroups = computed(() => { const groups = new Map<string, GraphNodeDefinition[]>(); for (const item of paletteResults.value) groups.set(item.category, [...(groups.get(item.category) ?? []), item]); return [...groups].map(([category,items]) => ({category,items})) })
const transformStyle = computed(() => ({ transform: `translate(${activeScope.value.viewport.x}px,${activeScope.value.viewport.y}px) scale(${activeScope.value.viewport.zoom})` }))
const gridStyle = computed(() => { const size = 24 * activeScope.value.viewport.zoom; return { backgroundSize: `${size}px ${size}px`, backgroundPosition: `${activeScope.value.viewport.x % size}px ${activeScope.value.viewport.y % size}px` } })
const visibleNodes = computed(() => { if (activeScope.value.nodes.length <= 300) return activeScope.value.nodes; const z = activeScope.value.viewport.zoom, margin = 400, left = -activeScope.value.viewport.x / z - margin, top = -activeScope.value.viewport.y / z - margin, right = left + canvasSize.width / z + margin * 2, bottom = top + canvasSize.height / z + margin * 2; return activeScope.value.nodes.filter(node => selectedNodes.has(node.uuid) || node.position.x + node.size.width >= left && node.position.x <= right && node.position.y + node.size.height >= top && node.position.y <= bottom) })
const visibleNodeIds = computed(() => new Set(visibleNodes.value.map(node => node.uuid)))
const visibleEdges = computed(() => activeScope.value.edges.filter(edge => visibleNodeIds.value.has(edge.from.nodeUuid) || visibleNodeIds.value.has(edge.to.nodeUuid)))
const activeNodeIndex = computed(() => new Map(activeScope.value.nodes.map(node => [node.uuid,node])))
const connectedInputPins = computed(() => new Set(activeScope.value.edges.map(edge => edge.to.pinUuid)))
const minimapBounds = computed(() => { const nodes=activeScope.value.nodes;if(!nodes.length)return{minX:0,minY:0,width:1,height:1};let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const node of nodes){minX=Math.min(minX,node.position.x);minY=Math.min(minY,node.position.y);maxX=Math.max(maxX,node.position.x+node.size.width);maxY=Math.max(maxY,node.position.y+node.size.height)}return{minX,minY,width:Math.max(1,maxX-minX),height:Math.max(1,maxY-minY)} })

function snapshot(): string { return serializeGraphDocument(graph.value) }
function compileNow(){if(compileTimer!==undefined){window.clearTimeout(compileTimer);compileTimer=undefined}compileResult.value=compileGraph(graph.value)}
function scheduleCompile(delay=55){if(compileTimer!==undefined)window.clearTimeout(compileTimer);compileTimer=window.setTimeout(compileNow,delay)}
function recordHistory() { if (restoring.value) return; const value = snapshot(); if (history.value[historyIndex.value] === value) return; history.value = history.value.slice(0, historyIndex.value + 1); history.value.push(value); if (history.value.length > 100) history.value.shift(); historyIndex.value = history.value.length - 1 }
function markDirty() { dirty.value = true; triggerRef(graph); scheduleCompile(); recordHistory() }
function markDirtyLive() { dirty.value = true; triggerRef(graph); scheduleCompile(140) }
function restore(source: string) { restoring.value = true; graph.value = parseGraphDocument(source); if (activeScopeUuid.value !== 'main' && !graph.value.routines.some(item => item.uuid === activeScopeUuid.value)) activeScopeUuid.value = 'main'; selectedNodes.clear(); pendingWire.value = null; compileNow(); nextTick(() => { restoring.value = false }) }
function undo() { if (!canUndo.value) return; historyIndex.value--; restore(history.value[historyIndex.value]); dirty.value = true }
function redo() { if (!canRedo.value) return; historyIndex.value++; restore(history.value[historyIndex.value]); dirty.value = true }

function openGraph(uuid: string) { const asset = assetState.records.find(item => item.uuid === uuid && item.assetType === 'visualScript'); const source = readTextAsset(uuid); if (!asset || !source) return; try { graph.value = parseGraphDocument(source); activeScopeUuid.value = 'main'; studio.activeGraphUuid = uuid; assetState.selectedGuid = uuid; dirty.value = false; selectedNodes.clear(); history.value = [snapshot()]; historyIndex.value = 0; compileNow() } catch (error) { addEditorLog(error instanceof Error ? error.message : String(error), 'Script', 'error', uuid) } }
function createGraph() { const document = defaultVisualGraph(t('newVisualGraph')); const asset = createTextAsset(t('newVisualGraph'), 'visualScript', serializeGraphDocument(document), 'Assets/Visual Scripts'); pushHistory('Create visual graph asset'); openGraphAsset(asset.uuid); openGraph(asset.uuid); addEditorLog(t('visualGraphCreated', { name: asset.name }), 'Script') }
function saveGraph() { if (!activeAsset.value) return; compileNow(); const result = compileResult.value; if (!result.valid) { addEditorLog(t('graphCannotCompile'), 'Script', 'error', activeAsset.value.uuid); return } const previous=readTextAsset(activeAsset.value.uuid)??sourceFromHistory(),source = serializeGraphDocument(graph.value); if (!updateTextAsset(activeAsset.value.uuid, source)) return; gameplayRuntime.queueGraphHotReload(activeAsset.value.uuid, source, previous); for(const uuid of synchronizeLinkedScriptsForGraph(graph.value)){const linkedSource=readTextAsset(uuid);if(linkedSource!==null)gameplayRuntime.queueHotReload(uuid,linkedSource)} dirty.value = false; history.value[historyIndex.value] = source; pushHistory('Save visual graph', `visual-graph:${activeAsset.value.uuid}`); addEditorLog(t('visualGraphSaved', { name: activeAsset.value.name }), 'Script') }
function sourceFromHistory(){return history.value[historyIndex.value]??serializeGraphDocument(graph.value)}

function addNode(type: string) { const scope = activeScope.value, z = scope.viewport.zoom, x = (canvasSize.width * .5 - scope.viewport.x) / z - 112, y = (canvasSize.height * .45 - scope.viewport.y) / z - 50; const node = createGraphNode(type, x, y, graph.value, activeRoutine.value); scope.nodes.push(node); selectedNodes.clear(); selectedNodes.add(node.uuid); paletteSearch.value = ''; markDirty() }
function addFirstPaletteNode() { const first = paletteResults.value[0]; if (first) addNode(first.type) }
function selectNode(event: PointerEvent, node: GraphNode) { if (!event.ctrlKey && !event.metaKey && !event.shiftKey) selectedNodes.clear(); if ((event.ctrlKey || event.metaKey) && selectedNodes.has(node.uuid)) selectedNodes.delete(node.uuid); else selectedNodes.add(node.uuid) }
function startNodeDrag(event: PointerEvent, node: GraphNode) { selectNode(event,node); recordHistory(); const starts = new Map(activeScope.value.nodes.filter(item => selectedNodes.has(item.uuid)).map(item => [item.uuid,{...item.position}])), sx=event.clientX, sy=event.clientY, z=activeScope.value.viewport.zoom; const move=(e:PointerEvent)=>{for(const [uuid,start] of starts){const item=activeNodeIndex.value.get(uuid);if(item){item.position.x=start.x+(e.clientX-sx)/z;item.position.y=start.y+(e.clientY-sy)/z}} dirty.value=true;triggerRef(graph)}; const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);recordHistory()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up) }
function startCommentDrag(event: PointerEvent, comment: GraphComment) { recordHistory(); const start={...comment.position},sx=event.clientX,sy=event.clientY,z=activeScope.value.viewport.zoom;const move=(e:PointerEvent)=>{comment.position.x=start.x+(e.clientX-sx)/z;comment.position.y=start.y+(e.clientY-sy)/z;dirty.value=true;triggerRef(graph)};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);recordHistory()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up) }

function canvasPointerDown(event: PointerEvent) { if (event.button !== 0 && event.button !== 1) return; pendingWire.value = null; const scope=activeScope.value,rect=canvas.value!.getBoundingClientRect(), z=scope.viewport.zoom; if(event.shiftKey&&event.button===0){const gx=(event.clientX-rect.left-scope.viewport.x)/z,gy=(event.clientY-rect.top-scope.viewport.y)/z;selectionBox.value={startX:gx,startY:gy,x:event.clientX-rect.left,y:event.clientY-rect.top,width:0,height:0};const move=(e:PointerEvent)=>{if(!selectionBox.value)return;const x=e.clientX-rect.left,y=e.clientY-rect.top;selectionBox.value.x=Math.min(selectionBox.value.x,x);selectionBox.value.y=Math.min(selectionBox.value.y,y);selectionBox.value.width=Math.abs(x-(selectionBox.value.startX*z+scope.viewport.x));selectionBox.value.height=Math.abs(y-(selectionBox.value.startY*z+scope.viewport.y))};const up=()=>{const box=selectionBox.value;if(box){const left=(box.x-scope.viewport.x)/z,top=(box.y-scope.viewport.y)/z,right=left+box.width/z,bottom=top+box.height/z;selectedNodes.clear();for(const node of scope.nodes)if(node.position.x<=right&&node.position.x+node.size.width>=left&&node.position.y<=bottom&&node.position.y+node.size.height>=top)selectedNodes.add(node.uuid)}selectionBox.value=null;window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);return} selectedNodes.clear();const start={x:scope.viewport.x,y:scope.viewport.y},sx=event.clientX,sy=event.clientY;const move=(e:PointerEvent)=>{scope.viewport.x=start.x+e.clientX-sx;scope.viewport.y=start.y+e.clientY-sy;triggerRef(graph)};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);dirty.value=true;recordHistory()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up) }
function zoomCanvas(event: WheelEvent) { const scope=activeScope.value,rect=canvas.value!.getBoundingClientRect(), old=scope.viewport.zoom, next=Math.min(4,Math.max(.1,old*(event.deltaY<0?1.1:.9))),px=event.clientX-rect.left,py=event.clientY-rect.top;scope.viewport.x=px-(px-scope.viewport.x)*(next/old);scope.viewport.y=py-(py-scope.viewport.y)*(next/old);scope.viewport.zoom=next;dirty.value=true;triggerRef(graph) }
function changeZoom(delta:number){activeScope.value.viewport.zoom=Math.min(4,Math.max(.1,activeScope.value.viewport.zoom+delta));dirty.value=true;triggerRef(graph)}
function frameAll(){const scope=activeScope.value;if(!scope.nodes.length){scope.viewport={x:80,y:80,zoom:1};triggerRef(graph);return}const minX=Math.min(...scope.nodes.map(n=>n.position.x)),minY=Math.min(...scope.nodes.map(n=>n.position.y)),maxX=Math.max(...scope.nodes.map(n=>n.position.x+n.size.width)),maxY=Math.max(...scope.nodes.map(n=>n.position.y+n.size.height)),zoom=Math.min(1.2,Math.max(.1,Math.min((canvasSize.width-100)/(maxX-minX||1),(canvasSize.height-100)/(maxY-minY||1))));scope.viewport.zoom=zoom;scope.viewport.x=(canvasSize.width-(maxX-minX)*zoom)/2-minX*zoom;scope.viewport.y=(canvasSize.height-(maxY-minY)*zoom)/2-minY*zoom;triggerRef(graph)}

function pinClicked(node:GraphNode,pin:GraphPin){if(pin.direction==='output'){pendingWire.value={node,pin};return}const pending=pendingWire.value;if(!pending||pending.pin.kind!==pin.kind)return;if(pin.kind==='data'&&pending.pin.valueType!==pin.valueType&&pending.pin.valueType!=='Data'&&pin.valueType!=='Data'){addEditorLog(t('graphTypeMismatch',{source:pending.pin.valueType??'',target:pin.valueType??''}),'Script','warning');return}activeScope.value.edges=activeScope.value.edges.filter(edge=>edge.to.pinUuid!==pin.uuid);activeScope.value.edges.push({uuid:graphUuid(),from:{nodeUuid:pending.node.uuid,pinUuid:pending.pin.uuid},to:{nodeUuid:node.uuid,pinUuid:pin.uuid}});pendingWire.value=null;markDirty()}
