function edgeKind(edge:GraphEdge){const node=activeNodeIndex.value.get(edge.from.nodeUuid),pin=node?.pins.find(p=>p.uuid===edge.from.pinUuid);return pin?.kind==='execution'?'execution':pin?.valueType?.toLowerCase()??'data'}
