function duplicateSelected(){const scope=activeScope.value,originals=scope.nodes.filter(n=>selectedNodes.has(n.uuid)),map=new Map<string,string>(),pinMap=new Map<string,string>();const copies=originals.map(node=>{const copy=JSON.parse(JSON.stringify(node)) as GraphNode;copy.uuid=graphUuid();map.set(node.uuid,copy.uuid);copy.position.x+=32;copy.position.y+=32;for(const pin of copy.pins){const old=pin.uuid;pin.uuid=graphUuid();pinMap.set(old,pin.uuid)}return copy});const edges=scope.edges.filter(edge=>map.has(edge.from.nodeUuid)&&map.has(edge.to.nodeUuid)).map(edge=>({uuid:graphUuid(),from:{nodeUuid:map.get(edge.from.nodeUuid)!,pinUuid:pinMap.get(edge.from.pinUuid)!},to:{nodeUuid:map.get(edge.to.nodeUuid)!,pinUuid:pinMap.get(edge.to.pinUuid)!}}));scope.nodes.push(...copies);scope.edges.push(...edges);selectedNodes.clear();for(const copy of copies)selectedNodes.add(copy.uuid);markDirty()}
function deleteSelected(){if(!selectedNodes.size)return;const scope=activeScope.value;scope.nodes=scope.nodes.filter(node=>!selectedNodes.has(node.uuid));scope.edges=scope.edges.filter(edge=>!selectedNodes.has(edge.from.nodeUuid)&&!selectedNodes.has(edge.to.nodeUuid));graph.value.debug.breakpoints=graph.value.debug.breakpoints.filter(point=>!selectedNodes.has(point.nodeUuid));selectedNodes.clear();markDirty()}
function alignSelected(){const nodes=activeScope.value.nodes.filter(node=>selectedNodes.has(node.uuid));if(nodes.length<2)return;const x=Math.min(...nodes.map(node=>node.position.x));for(const node of nodes)node.position.x=x;markDirty()}
