function addComment(){const scope=activeScope.value;scope.comments.push({uuid:graphUuid(),text:t('graphComment'),position:{x:(canvasSize.width*.4-scope.viewport.x)/scope.viewport.zoom,y:(canvasSize.height*.3-scope.viewport.y)/scope.viewport.zoom},size:{width:360,height:220},color:'#5b8def',collapsed:false});markDirty()}

function addVariable(){graph.value.variables.push({uuid:graphUuid(),name:`variable_${graph.value.variables.length+1}`,valueType:'Number',defaultValue:0,exposed:true,serialized:true,group:t('graphVariables'),tooltip:'',minimum:null,maximum:null,step:.01,resourceType:null});markDirty()}
