function graphScopes(){return [graph.value as GraphCanvasScope,...graph.value.routines]}
function variableTypeChanged(variable:GraphVariable){variable.defaultValue=defaultGraphValue(variable.valueType);variable.resourceType=variable.valueType==='Resource'?'Resource':null;for(const scope of graphScopes())for(const node of scope.nodes.filter(node=>node.config.variableUuid===variable.uuid))for(const pin of node.pins.filter(pin=>pin.kind==='data')){pin.valueType=variable.valueType;pin.defaultValue=variable.defaultValue}markDirty()}
function removeVariable(uuid:string){graph.value.variables=graph.value.variables.filter(v=>v.uuid!==uuid);for(const scope of graphScopes()){scope.nodes=scope.nodes.filter(n=>n.config.variableUuid!==uuid);const ids=new Set(scope.nodes.map(node=>node.uuid));scope.edges=scope.edges.filter(edge=>ids.has(edge.from.nodeUuid)&&ids.has(edge.to.nodeUuid))}markDirty()}
function selectNodeVariable(node:GraphNode,event:Event){const uuid=(event.target as HTMLSelectElement).value,variable=graph.value.variables.find(v=>v.uuid===uuid);node.config.variableUuid=uuid;if(variable)for(const pin of node.pins.filter(pin=>pin.kind==='data')){pin.valueType=variable.valueType;pin.defaultValue=variable.defaultValue}markDirty()}
function selectNodeLocal(node:GraphNode,event:Event){const uuid=(event.target as HTMLSelectElement).value,local=activeRoutine.value?.locals.find(v=>v.uuid===uuid);node.config.localUuid=uuid;if(local)for(const pin of node.pins.filter(pin=>pin.kind==='data')){pin.valueType=local.valueType;pin.defaultValue=local.defaultValue}markDirty()}
function setVariableDefault(variable:GraphVariable,event:Event){const text=(event.target as HTMLInputElement).value;if(variable.valueType==='Number')variable.defaultValue=Number.isFinite(Number(text))?Number(text):0;else if(variable.valueType==='Boolean')variable.defaultValue=/^(true|1|yes)$/i.test(text);else if(variable.valueType==='Vec2'){const values=text.split(/[, ]+/).map(Number);variable.defaultValue=[Number.isFinite(values[0])?values[0]:0,Number.isFinite(values[1])?values[1]:0]}else if(variable.valueType==='Data'){try{variable.defaultValue=JSON.parse(text) as GraphValue}catch{variable.defaultValue=null}}else variable.defaultValue=text;markDirty()}

function setPinNumber(pin:GraphPin,event:Event){const value=Number((event.target as HTMLInputElement).value);pin.defaultValue=Number.isFinite(value)?value:0;markDirty()}
function setPinText(pin:GraphPin,event:Event){const value=(event.target as HTMLInputElement).value;if(pin.valueType==='Data'){try{pin.defaultValue=JSON.parse(value) as GraphValue}catch{pin.defaultValue=value}}else pin.defaultValue=value;markDirty()}
function setPinVector(pin:GraphPin,index:0|1,event:Event){const value=Array.isArray(pin.defaultValue)?[Number(pin.defaultValue[0])||0,Number(pin.defaultValue[1])||0]:[0,0];value[index]=Number((event.target as HTMLInputElement).value)||0;pin.defaultValue=value;markDirty()}
function setLiteralNumber(node:GraphNode,event:Event){const value=Number((event.target as HTMLInputElement).value);node.config.value=Number.isFinite(value)?value:0;markDirty()}
function setLiteralVector(node:GraphNode,index:0|1,event:Event){const value=Array.isArray(node.config.value)?[Number(node.config.value[0])||0,Number(node.config.value[1])||0]:[0,0];value[index]=Number((event.target as HTMLInputElement).value)||0;node.config.value=value;markDirty()}
function updatePinNumber(pin:GraphPin,event:Event){const value=Number((event.target as HTMLInputElement).value);pin.defaultValue=Number.isFinite(value)?value:0;markDirtyLive()}
function updatePinText(pin:GraphPin,event:Event){const value=(event.target as HTMLInputElement).value;if(pin.valueType==='Data'){try{pin.defaultValue=JSON.parse(value) as GraphValue}catch{pin.defaultValue=value}}else pin.defaultValue=value;markDirtyLive()}
function updatePinVector(pin:GraphPin,index:0|1,event:Event){const value=Array.isArray(pin.defaultValue)?[Number(pin.defaultValue[0])||0,Number(pin.defaultValue[1])||0]:[0,0];value[index]=Number((event.target as HTMLInputElement).value)||0;pin.defaultValue=value;markDirtyLive()}
function updateLiteralNumber(node:GraphNode,event:Event){const value=Number((event.target as HTMLInputElement).value);node.config.value=Number.isFinite(value)?value:0;markDirtyLive()}
function updateLiteralVector(node:GraphNode,index:0|1,event:Event){const value=Array.isArray(node.config.value)?[Number(node.config.value[0])||0,Number(node.config.value[1])||0]:[0,0];value[index]=Number((event.target as HTMLInputElement).value)||0;node.config.value=value;markDirtyLive()}
function updateLiteralText(node:GraphNode,event:Event){node.config.value=(event.target as HTMLInputElement).value;markDirtyLive()}
function setLiteralText(node:GraphNode,event:Event){node.config.value=(event.target as HTMLInputElement).value;markDirty()}
