function setNodeCodeSource(node:GraphNode,event:Event){const value=(event.target as HTMLTextAreaElement).value.slice(0,64_000);if(node.type.startsWith('code.'))node.config.source=value;else node.config.rhaiSourceOverride=value;node.size.height=Math.max(node.size.height,190);markDirty()}
function updateNodeCodeSource(node:GraphNode,event:Event){const value=(event.target as HTMLTextAreaElement).value.slice(0,64_000);if(node.type.startsWith('code.'))node.config.source=value;else node.config.rhaiSourceOverride=value;node.size.height=Math.max(node.size.height,190);markDirtyLive()}
