function scopeChanged(){selectedNodes.clear();pendingWire.value=null;triggerRef(graph)}
function setActiveScope(uuid:string){activeScopeUuid.value=uuid;scopeChanged()}
function replaceGraph(document:NovaGraphDocument){graph.value=parseGraphDocument(serializeGraphDocument(document));if(activeScopeUuid.value!=='main'&&!graph.value.routines.some(item=>item.uuid===activeScopeUuid.value))activeScopeUuid.value='main';selectedNodes.clear();markDirty()}
function hasBreakpoint(nodeUuid:string){return graph.value.debug.breakpoints.some(point=>point.nodeUuid===nodeUuid&&point.enabled)}
function toggleBreakpoint(nodeUuid:string){const existing=graph.value.debug.breakpoints.find(point=>point.nodeUuid===nodeUuid);if(existing)existing.enabled=!existing.enabled;else graph.value.debug.breakpoints.push({nodeUuid,enabled:true,condition:'',hitCondition:0,logMessage:'',hitCount:0});markDirty()}
function hasNodeError(nodeUuid:string){return graphDebugState.errors.some(item=>item.graphUuid===graph.value.uuid&&item.nodeUuid===nodeUuid)}

function focusDiagnostic(diagnostic:GraphDiagnostic){if(!diagnostic.nodeUuid)return;const owner=graphScopes().map((scope,index)=>({scope,uuid:index===0?'main':graph.value.routines[index-1].uuid})).find(item=>item.scope.nodes.some(node=>node.uuid===diagnostic.nodeUuid));if(!owner)return;activeScopeUuid.value=owner.uuid;const node=owner.scope.nodes.find(item=>item.uuid===diagnostic.nodeUuid)!;selectedNodes.clear();selectedNodes.add(node.uuid);owner.scope.viewport.x=canvasSize.width*.5-(node.position.x+node.size.width*.5)*owner.scope.viewport.zoom;owner.scope.viewport.y=canvasSize.height*.5-(node.position.y+node.size.height*.5)*owner.scope.viewport.zoom}
function onKeydown(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();saveGraph()}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo()}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo()}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();duplicateSelected()}else if(event.key==='Delete'||event.key==='Backspace'){if((event.target as HTMLElement).matches('input,textarea,select'))return;event.preventDefault();deleteSelected()}else if(event.key===' '&&!((event.target as HTMLElement).matches('input,textarea'))){event.preventDefault();studio.paletteOpen=true;nextTick(()=>paletteInput.value?.focus())}else if(event.key==='Escape')pendingWire.value=null}

