function commentStyle(comment:GraphComment){return{left:`${comment.position.x}px`,top:`${comment.position.y}px`,width:`${comment.size.width}px`,height:`${comment.collapsed?34:comment.size.height}px`,background:`color-mix(in srgb,${comment.color} 10%,transparent)`}}
