function localizedCategory(category:string){const keys:Record<string,string>={Events:'graphCategoryEvents',Flow:'graphCategoryFlow',Values:'graphCategoryValues',Variables:'graphCategoryVariables',Math:'graphCategoryMath',Comparison:'graphCategoryComparison',Conversion:'graphCategoryConversion',Functions:'graphCategoryFunctions',Libraries:'graphCategoryLibraries'};return t(keys[category]??category.toLowerCase())}
function miniX(x:number){const b=minimapBounds.value;return 8+(x-b.minX)/b.width*184}function miniY(y:number){const b=minimapBounds.value;return 18+(y-b.minY)/b.height*94}
const selectionBoxStyle=computed(()=>selectionBox.value?{left:`${selectionBox.value.x}px`,top:`${selectionBox.value.y}px`,width:`${selectionBox.value.width}px`,height:`${selectionBox.value.height}px`}:{})

function pointerMove(event:PointerEvent){if(!pendingWire.value||!canvas.value)return;const rect=canvas.value.getBoundingClientRect(),scope=activeScope.value;pointerGraph.value={x:(event.clientX-rect.left-scope.viewport.x)/scope.viewport.zoom,y:(event.clientY-rect.top-scope.viewport.y)/scope.viewport.zoom}}
function linkedGraphSynchronized(event:Event){const uuid=(event as CustomEvent<{graphAssetUuid:string}>).detail?.graphAssetUuid;if(uuid&&uuid===activeAsset.value?.uuid&&!dirty.value)openGraph(uuid)}
watch(()=>studio.activeGraphUuid,(uuid,previous)=>{if(uuid&&uuid!==previous)openGraph(uuid)})
watch(()=>assetState.generation,()=>{if(!activeAsset.value&&graphAssets.value[0])openGraph(graphAssets.value[0].uuid)})
