onBeforeUnmount(()=>{window.removeEventListener('pointermove',pointerMove);window.removeEventListener('nova-linked-graph-synchronized',linkedGraphSynchronized);if(compileTimer!==undefined)window.clearTimeout(compileTimer);resizeObserver?.disconnect()})
